#[no_mangle]
pub extern "C" fn png_read_IDAT_data(
    mut png_ptr: png_structrp,
    mut output: png_bytep,
    mut avail_out: png_alloc_size_t,
) {
    unsafe {
        // SAFETY: png_ptr is required by the caller to be a valid mutable pointer to png_struct.
        let png = &mut *png_ptr;

        png.zstream.next_out = output as *mut Bytef;
        png.zstream.avail_out = 0 as uInt;

        if output.is_null() {
            avail_out = 0 as png_alloc_size_t;
        }

        loop {
            let ret: c_int;
            let mut tmpbuf: [png_byte; 1024] = [0; 1024];

            if png.zstream.avail_in == 0 as c_uint {
                while png.idat_size == 0 as c_uint {
                    png_crc_finish(png_ptr, 0 as png_uint_32);
                    png.idat_size = png_read_chunk_header(png_ptr);
                    if png.chunk_name != png_IDAT {
                        png_error(
                            png_ptr,
                            b"Not enough image data\0" as *const u8 as png_const_charp,
                        );
                    }
                }

                let mut avail_in: uInt = png.IDAT_read_size;
                if avail_in > png.idat_size {
                    avail_in = png.idat_size;
                }

                let buffer = png_read_buffer(png_ptr, avail_in as png_alloc_size_t, 0 as c_int);
                png_crc_read(png_ptr, buffer, avail_in as png_uint_32);
                png.idat_size = (png.idat_size as c_uint).wrapping_sub(avail_in as c_uint)
                    as png_uint_32;
                png.zstream.next_in = buffer as *const Bytef;
                png.zstream.avail_in = avail_in;
            }

            if !output.is_null() {
                let mut out: uInt = ZLIB_IO_MAX;
                if (out as png_alloc_size_t) > avail_out {
                    out = avail_out as uInt;
                }
                avail_out = (avail_out as c_ulong).wrapping_sub(out as c_ulong)
                    as png_alloc_size_t;
                png.zstream.avail_out = out;
            } else {
                png.zstream.next_out = tmpbuf.as_mut_ptr() as *mut Bytef;
                png.zstream.avail_out = 1024 as uInt;
            }

            ret = png_zlib_inflate(png_ptr, 0 as c_int);

            if !output.is_null() {
                avail_out = (avail_out as c_ulong).wrapping_add(png.zstream.avail_out as c_ulong)
                    as png_alloc_size_t;
            } else {
                avail_out = (avail_out as c_ulong)
                    .wrapping_add((1024usize.wrapping_sub(png.zstream.avail_out as usize)) as c_ulong)
                    as png_alloc_size_t;
            }

            png.zstream.avail_out = 0 as uInt;

            if ret == Z_STREAM_END {
                png.zstream.next_out = ::core::ptr::null_mut::<Bytef>();
                png.mode |= PNG_AFTER_IDAT as c_uint;
                png.flags |= PNG_FLAG_ZSTREAM_ENDED;
                if png.zstream.avail_in > 0 as c_uint || png.idat_size > 0 as c_uint {
                    png_chunk_benign_error(
                        png_ptr,
                        b"Extra compressed data\0" as *const u8 as png_const_charp,
                    );
                }
                break;
            } else {
                if ret != Z_OK {
                    png_zstream_error(png_ptr, ret);
                    if !output.is_null() {
                        png_chunk_error(png_ptr, png.zstream.msg as png_const_charp);
                    } else {
                        png_chunk_benign_error(png_ptr, png.zstream.msg as png_const_charp);
                        return;
                    }
                }
                if !(avail_out > 0 as png_alloc_size_t) {
                    break;
                }
            }
        }

        if avail_out > 0 as png_alloc_size_t {
            if !output.is_null() {
                png_error(
                    png_ptr,
                    b"Not enough image data\0" as *const u8 as png_const_charp,
                );
            } else {
                png_chunk_benign_error(
                    png_ptr,
                    b"Too much image data\0" as *const u8 as png_const_charp,
                );
            }
        }
    }
}
