unsafe fn gen_codes(
    mut tree: *mut ct_data,
    mut max_code: c_int,
    mut bl_count: *mut ushf,
) {
    let mut next_code: [ush; 16] = [0; 16];
    let mut code: c_uint = 0;
    let mut bits: c_int = 1;

    while bits <= MAX_BITS {
        // SAFETY: bl_count points to a valid array indexed from 0..=MAX_BITS as required by the caller.
        code = (code.wrapping_add(unsafe { *bl_count.offset((bits - 1) as isize) as c_uint })) << 1;
        next_code[bits as usize] = code as ush;
        bits += 1;
    }

    let mut n: c_int = 0;
    let mut tp = tree;
    while n <= max_code {
        // SAFETY: tp starts at tree and advances one element per iteration up to max_code inclusive, matching the original tree.offset(n).
        let len = unsafe { (*tp).dl.len as c_int };
        if len != 0 {
            let idx = len as usize;
            let code_u = next_code[idx];
            next_code[idx] = code_u.wrapping_add(1);
            // SAFETY: tp points to the current valid ct_data element in the tree array.
            unsafe {
                (*tp).fc.code = bi_reverse(code_u as c_uint, len) as ush;
            }
        }
        n += 1;
        // SAFETY: advancing by one stays within the same valid tree array traversed by the original code.
        tp = unsafe { tp.add(1) };
    }
}
